  sg_v2_m: { en: `Indeed, prayer has been decreed for the believers at fixed times.`, ms: ``, tur: ``, urd: ``, ben: ``, fas: ``, zh: ``, yue: ``, ja: ``, ru: ``, es: ``, ko: ``, ta: ``, si: `` },
