  sg_v3_p: { en: `The Quran points to the times in general terms; the exact start and end of each was shown by the Prophet ﷺ.`, ms: ``, tur: ``, urd: ``, ben: ``, fas: ``, zh: ``, yue: ``, ja: ``, ru: ``, es: ``, ko: ``, ta: ``, si: `` },
